        frames.update(self._step_evaluated_evaluate_30(frames))
        frames.update(self._step_evaluated_classify_31(frames))
        frames.update(self._step_evaluated_summarize_32(frames))
        frames.update(self._step_evaluated_publish_summary_33(frames))

        # Step method: demand
        demand = frames["prepared__demand"].alias("order")
        assert_schema(demand, ORDER_SCHEMA, name="Order", mode="strict")

        # Step method: allocations
        allocations = frames["planned__allocations"].alias("fulfillment_allocation")
        assert_schema(allocations, FULFILLMENT_ALLOCATION_SCHEMA, name="FulfillmentAllocation", mode="strict")

        # Step method: backorders
        backorders = frames["planned__backorders"].alias("fulfillment_backorder")
        assert_schema(backorders, FULFILLMENT_BACKORDER_SCHEMA, name="FulfillmentBackorder", mode="strict")

        # Step method: plans
        plans = frames["planned__plans"].alias("fulfillment_plan")
        assert_schema(plans, FULFILLMENT_PLAN_SCHEMA, name="FulfillmentPlan", mode="strict")

        # Step method: reconciliation
        reconciliation = frames["reconciled__reconciliation"].alias("fulfillment_reconciliation")
